class Solution:
    def countValidSequences(self, n: int, k: int) -> int:
        import sys
        sys.setrecursionlimit(10**7)
        from functools import lru_cache
        MOD = 10**9 + 7
        @lru_cache(maxsize=None)
        def f(rem, ln, e):
            if ln == 0:
                return 1 if (rem == 0 and e) else 0
            ans = 0
            for v in range(1, rem - ln + 2):
                ans += f(rem - v, ln - 1, e or v % 2 == 0)
            return ans % MOD
        return f(n, k, False)

