class Solution {
public:
    int MOD = 1000000007;
    vector<vector<vector<long long>>> memo;
    long long f(int rem, int ln, int e) {
        if (ln == 0) return (rem == 0 && e) ? 1 : 0;
        if (memo[rem][ln][e] != -1) return memo[rem][ln][e];
        long long ans = 0;
        for (int v = 1; v <= rem - ln + 1; v++)
            ans = (ans + f(rem - v, ln - 1, e || v % 2 == 0)) % MOD;
        return memo[rem][ln][e] = ans;
    }
    int countValidSequences(int n, int k) {
        memo.assign(n + 1, vector<vector<long long>>(k + 1, vector<long long>(2, -1)));
        return (int)f(n, k, 0);
    }
};

