class Solution {
public:
    const long long MOD = 1000000007;
    vector<long long> fact, inv_fact;
    long long pw(long long b, long long e) {
        long long r = 1; b %= MOD;
        while (e) { if (e & 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; }
        return r;
    }
    long long C(long long a, long long b) {
        if (b < 0 || b > a) return 0;
        return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD;
    }
    int countValidSequences(int n, int k) {
        int N = n + 1;
        fact.resize(N + 1); inv_fact.resize(N + 1);
        fact[0] = 1;
        for (int i = 1; i <= N; i++) fact[i] = fact[i - 1] * i % MOD;
        inv_fact[N] = pw(fact[N], MOD - 2);
        for (int i = N; i >= 1; i--) inv_fact[i - 1] = inv_fact[i] * i % MOD;
        long long total = C(n - 1, k - 1);
        long long oddOnly = ((n - k) % 2 == 0) ? C((long long)(n - k) / 2 + k - 1, k - 1) : 0;
        return (int)((total - oddOnly % MOD + MOD) % MOD);
    }
};

